using System;
using System.IO;
using Microsoft.Win32;
internal static class UserInstallationTests {
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 [STAThread] static void Main(){string root=Path.Combine(Path.GetTempPath(),"Remsup-install-tests-"+Guid.NewGuid().ToString("N")),key=@"Software\RemsupInstallTests\"+Guid.NewGuid().ToString("N");Directory.CreateDirectory(root);string desktop=Path.Combine(root,"Desktop"),start=Path.Combine(root,"Start");Directory.CreateDirectory(desktop);Directory.CreateDirectory(start);var install=new UserInstallation(Path.Combine(root,"Programs","Remsup"),desktop,start,key,key+"Run");Directory.CreateDirectory(install.DirectoryPath);File.WriteAllText(install.Executable,"fixture");
 try {
  install.Register(new InstallChoice{Desktop=false,StartMenu=false},"v1.43",false);Check(!File.Exists(install.DesktopShortcut)&&!File.Exists(install.StartShortcut),"unchecked icons created");
  install.Register(new InstallChoice(),"v1.43",true);Check(File.Exists(install.DesktopShortcut)&&File.Exists(install.StartShortcut),"icons missing");using(var run=Registry.CurrentUser.OpenSubKey(key+"Run")){Check((string)run.GetValue(UserInstallation.RunName)=="\""+install.Executable+"\"","startup path not stable");}string target=Target(install.DesktopShortcut);Check(target==install.Executable,"shortcut not stable");install.Register(install.ReadChoice(),"v1.44",false);Check(Target(install.DesktopShortcut)==target,"update changed icon target");using(var registration=Registry.CurrentUser.OpenSubKey(key)){Check((string)registration.GetValue("DisplayVersion")=="v1.44"&&(string)registration.GetValue("UninstallString")=="\""+target+"\" --uninstall","app registration/version wrong");}
  install.RemoveRegistration();Check(!File.Exists(install.DesktopShortcut)&&!File.Exists(install.StartShortcut)&&Registry.CurrentUser.OpenSubKey(key)==null,"uninstall registration failed");string unrelated=Path.Combine(install.DirectoryPath,"user.txt");File.WriteAllText(unrelated,"preserve");using(var locked=new FileStream(install.Executable,FileMode.Open,FileAccess.Read,FileShare.Read)){Check(!install.CleanupFiles()&&File.Exists(install.Executable),"locked app not preserved");}Check(!install.CleanupFiles()&&File.Exists(unrelated),"unrelated data removed");File.Delete(unrelated);Check(install.CleanupFiles()&&!Directory.Exists(install.DirectoryPath),"uninstall folder cleanup failed");
  Directory.CreateDirectory(install.DirectoryPath);File.WriteAllText(install.Executable,"fixture");install.Register(new InstallChoice{Desktop=false,StartMenu=false},"v1.44",false);string status=Path.Combine(root,"uninstall-status.txt");int helper=UninstallManager.Schedule(install,false,status);using(var process=System.Diagnostics.Process.GetProcessById(helper)){Check(process.WaitForExit(15000),"uninstall worker remained running");}Check(!Directory.Exists(install.DirectoryPath)&&File.ReadAllText(status).Contains("Remsup removed"),"real cleanup worker did not remove installed files");
  Directory.CreateDirectory(install.DirectoryPath);File.WriteAllText(install.Executable,"fixture");string settings=Path.Combine(root,"settings.txt"),data=Path.Combine(root,"vault");Directory.CreateDirectory(data);File.WriteAllText(settings,"fixture");File.WriteAllText(Path.Combine(data,"devices-v2.json"),"fixture");File.WriteAllText(Path.Combine(data,"devices.json"),"fixture");File.WriteAllText(Path.Combine(data,"unrelated.txt"),"preserve");helper=UninstallManager.Schedule(install,true,status,settings,data);using(var process=System.Diagnostics.Process.GetProcessById(helper)){Check(process.WaitForExit(15000),"explicit data cleanup worker remained running");}Check(!File.Exists(settings)&&!File.Exists(Path.Combine(data,"devices-v2.json"))&&!File.Exists(Path.Combine(data,"devices.json"))&&File.Exists(Path.Combine(data,"unrelated.txt")),"explicit deletion failed or touched unrelated data");
  Console.WriteLine("Per-user installation, icon choices, stable shortcuts/version, unregister and locked/unrelated cleanup PASS");
 }finally{Registry.CurrentUser.DeleteSubKeyTree(key,false);Registry.CurrentUser.DeleteSubKeyTree(key+"Run",false);try{Directory.Delete(root,true);}catch{}}
 }
 static string Target(string path){dynamic shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));dynamic shortcut=shell.CreateShortcut(path);try{return shortcut.TargetPath;}finally{System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shortcut);System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);}}
}
